import sys

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]
    vPos = []
    kPos = []
    xPos = []

    for i, c in enumerate(s):
        if c == 'V':
            vPos.append(i)
        elif c == 'K':
            kPos.append(i)
        else:
            xPos.append(i)

    vCount = len(vPos)
    kCount = len(kPos)
    xCount = len(xPos)

    # Initialize 4D DP array with a large number
    INF = 10**15
    dp = [[[[INF for _ in range(2)] for _ in range(xCount + 1)] for _ in range(kCount + 1)] for _ in range(vCount + 1)]
    dp[0][0][0][0] = 0

    def countSmaller(arr, start, val):
        cnt = 0
        for i in range(start, len(arr)):
            if arr[i] < val:
                cnt += 1
        return cnt

    for vIdx in range(vCount + 1):
        for kIdx in range(kCount + 1):
            for xIdx in range(xCount + 1):
                for t in range(2):
                    cost = dp[vIdx][kIdx][xIdx][t]
                    if cost == INF:
                        continue
                    if vIdx < vCount:
                        posV = vPos[vIdx]
                        moves = (countSmaller(vPos, vIdx, posV) +
                                 countSmaller(kPos, kIdx, posV) +
                                 countSmaller(xPos, xIdx, posV))
                        if dp[vIdx + 1][kIdx][xIdx][1] > cost + moves:
                            dp[vIdx + 1][kIdx][xIdx][1] = cost + moves
                    if kIdx < kCount and t == 0:
                        posK = kPos[kIdx]
                        moves = (countSmaller(vPos, vIdx, posK) +
                                 countSmaller(kPos, kIdx, posK) +
                                 countSmaller(xPos, xIdx, posK))
                        if dp[vIdx][kIdx + 1][xIdx][0] > cost + moves:
                            dp[vIdx][kIdx + 1][xIdx][0] = cost + moves
                    if xIdx < xCount:
                        posX = xPos[xIdx]
                        moves = (countSmaller(vPos, vIdx, posX) +
                                 countSmaller(kPos, kIdx, posX) +
                                 countSmaller(xPos, xIdx, posX))
                        if dp[vIdx][kIdx][xIdx + 1][0] > cost + moves:
                            dp[vIdx][kIdx][xIdx + 1][0] = cost + moves

    minCost = min(dp[vCount][kCount][xCount])
    print(minCost)

if __name__ == "__main__":
    main()

